114:   const ctx = audio.context; const now = ctx.currentTime;
115:   const osc = ctx.createOscillator(); const wobble = ctx.createOscillator();
116:   const wobbleGain = ctx.createGain(); const filter = ctx.createBiquadFilter(); const volume = ctx.createGain();
117:   osc.type = 'sawtooth'; osc.frequency.setValueAtTime(72 + Math.random() * 28, now);
118:   osc.frequency.exponentialRampToValueAtTime(42 + Math.random() * 16, now + 0.8);
119:   wobble.frequency.value = 5; wobbleGain.gain.value = 7; wobble.connect(wobbleGain); wobbleGain.connect(osc.frequency);
120:   filter.type = 'lowpass'; filter.frequency.value = 360;
121:   volume.gain.setValueAtTime(0.0001, now); volume.gain.linearRampToValueAtTime(0.035, now + 0.12);
122:   volume.gain.exponentialRampToValueAtTime(0.0001, now + 0.95);
123:   osc.connect(filter); filter.connect(volume); volume.connect(audio.master);
124:   wobble.start(now); osc.start(now); wobble.stop(now + 1); osc.stop(now + 1);
