193: function applyZombieAsset(zombie) {
194:   if (!zombieAsset.root || !window.THREE.SkeletonUtils) return false;
195:   const replacement = THREE.SkeletonUtils.clone(zombieAsset.root);
196:   replacement.traverse((part) => {
197:     if (!part.isMesh) return;
198:     part.castShadow = true;
199:     part.receiveShadow = true;
200:     const cloneMaterial = (material) => {
201:       const instance = material.clone();
202:       if (instance.emissive) instance.userData.baseEmissive = instance.emissive.clone();
203:       return instance;
204:     };
205:     part.material = Array.isArray(part.material) ? part.material.map(cloneMaterial) : cloneMaterial(part.material);
206:   });
207:   replacement.updateWorldMatrix(true, true);
208:   const bounds = new THREE.Box3().setFromObject(replacement);
209:   const size = bounds.getSize(new THREE.Vector3());
210:   if (!Number.isFinite(size.y) || size.y < 0.1) return false;
211:   const center = bounds.getCenter(new THREE.Vector3());
212:   const scale = 1.65 / size.y;
213:   replacement.scale.setScalar(scale);
214:   replacement.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
215:   const root = new THREE.Group();
216:   root.add(replacement);
217:   if (zombie.model) {
218:     scene.remove(zombie.model);
219:     zombie.model.traverse((part) => { if (part.geometry) part.geometry.dispose(); });
220:   }
221:   scene.add(root);
222:   zombie.model = root;
223:   zombie.limbs = [];
224:   zombie.mixer = new THREE.AnimationMixer(replacement);
225:   if (zombieAsset.clips.length) {
226:     zombie.action = zombie.mixer.clipAction(zombieAsset.clips[0]);
227:     zombie.action.setLoop(THREE.LoopRepeat, Infinity);
228:     zombie.action.play();
229:   }
230:   syncEntity(zombie);
231:   return true;
232: }
233: function loadZombieAsset() {
234:   zombieAsset.ready = new Promise((resolve) => {
235:     if (!THREE.GLTFLoader) {
236:       zombieAsset.failed = true;
237:       console.warn('GLTFLoader unavailable; using procedural zombies.');
238:       resolve(false);
239:       return;
240:     }
241:     const loader = new THREE.GLTFLoader();
242:     loader.load('public/models/zombie.glb', (gltf) => {
243:       zombieAsset.root = gltf.scene;
244:       zombieAsset.clips = gltf.animations || [];
245:       for (const zombie of world.zombies) applyZombieAsset(zombie);
246:       resolve(true);
247:     }, undefined, (error) => {
248:       zombieAsset.failed = true;
249:       console.warn('Zombie model failed to load; using procedural fallback.', error);
250:       resolve(false);
251:     });
252:   });
253:   return zombieAsset.ready;
254: }
