197: function applyZombieAsset(zombie) {
198:   if (!zombieAsset.root || !window.THREE.SkeletonUtils) return false;
199:   const replacement = THREE.SkeletonUtils.clone(zombieAsset.root);
200:   replacement.traverse((part) => {
201:     if (!part.isMesh) return;
202:     part.castShadow = true;
203:     part.receiveShadow = true;
204:     const cloneMaterial = (material) => {
205:       const instance = material.clone();
206:       if (instance.emissive) instance.userData.baseEmissive = instance.emissive.clone();
207:       return instance;
208:     };
209:     part.material = Array.isArray(part.material) ? part.material.map(cloneMaterial) : cloneMaterial(part.material);
210:   });
211:   replacement.updateWorldMatrix(true, true);
212:   const bounds = new THREE.Box3().setFromObject(replacement);
213:   const size = bounds.getSize(new THREE.Vector3());
214:   if (!Number.isFinite(size.y) || size.y < 0.1) return false;
215:   const center = bounds.getCenter(new THREE.Vector3());
216:   const scale = 1.65 / size.y;
217:   replacement.scale.setScalar(scale);
218:   replacement.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
219:   const root = new THREE.Group();
220:   root.add(replacement);
221:   if (zombie.model) {
222:     scene.remove(zombie.model);
223:     zombie.model.traverse((part) => { if (part.geometry) part.geometry.dispose(); });
224:   }
225:   scene.add(root);
226:   zombie.model = root;
227:   zombie.limbs = [];
228:   zombie.mixer = new THREE.AnimationMixer(replacement);
229:   if (zombieAsset.clips.length) {
230:     zombie.action = zombie.mixer.clipAction(zombieAsset.clips[0]);
231:     zombie.action.setLoop(THREE.LoopRepeat, Infinity);
232:     zombie.action.play();
233:   }
234:   syncEntity(zombie);
235:   return true;
236: }
