504: function updatePlayer(dt) {
505:   const player = world.player;
506:   let dx = 0; let dy = 0;
507:   if (input.keys.has('w') || input.keys.has('arrowup')) dy -= 1;
508:   if (input.keys.has('s') || input.keys.has('arrowdown')) dy += 1;
509:   if (input.keys.has('a') || input.keys.has('arrowleft')) dx -= 1;
510:   if (input.keys.has('d') || input.keys.has('arrowright')) dx += 1;
511:   if (input.touchStick.active) { dx += input.touchStick.x; dy += input.touchStick.y; }
512:   const length = Math.hypot(dx, dy) || 1;
513:   player.x = clamp(player.x + dx / length * player.speed * dt, 20, world.width - 20);
514:   player.y = clamp(player.y + dy / length * player.speed * dt, 20, world.height - 20);
515:   if (player.regen > 0 && player.hp < player.maxHp) player.hp = Math.min(player.maxHp, player.hp + player.regen * dt);
516:   player.orbitTimer = Math.max(0, player.orbitTimer - dt);
517:   let target = null; let targetDistance = 650;
518:   for (const zombie of world.zombies) {
519:     const distance = dist(player.x, player.y, zombie.x, zombie.y);
520:     if (distance < targetDistance) { target = zombie; targetDistance = distance; }
521:   }
522:   if (target) {
523:     player.angle = Math.atan2(target.y - player.y, target.x - player.x);
524:     player.fireCooldown -= dt;
525:     if (player.fireCooldown <= 0) { fireBullet(); player.fireCooldown = player.fireRate; }
526:   } else player.fireCooldown = Math.min(player.fireCooldown, 0);
527:   player.model.rotation.y = Math.PI / 2 - player.angle;
528:   syncEntity(player);
529:   player.bombCooldown = Math.max(0, player.bombCooldown - dt);
