510: function updatePlayer(dt) {
511:   const player = world.player;
512:   let dx = 0; let dy = 0;
513:   if (input.keys.has('w') || input.keys.has('arrowup')) dy -= 1;
514:   if (input.keys.has('s') || input.keys.has('arrowdown')) dy += 1;
515:   if (input.keys.has('a') || input.keys.has('arrowleft')) dx -= 1;
516:   if (input.keys.has('d') || input.keys.has('arrowright')) dx += 1;
517:   if (input.touchStick.active) { dx += input.touchStick.x; dy += input.touchStick.y; }
518:   const length = Math.hypot(dx, dy) || 1;
519:   player.x = clamp(player.x + dx / length * player.speed * dt, 20, world.width - 20);
520:   player.y = clamp(player.y + dy / length * player.speed * dt, 20, world.height - 20);
521:   if (player.regen > 0 && player.hp < player.maxHp) player.hp = Math.min(player.maxHp, player.hp + player.regen * dt);
522:   player.orbitTimer = Math.max(0, player.orbitTimer - dt);
523:   let target = null; let targetDistance = 650;
524:   for (const zombie of world.zombies) {
525:     const distance = dist(player.x, player.y, zombie.x, zombie.y);
526:     if (distance < targetDistance) { target = zombie; targetDistance = distance; }
527:   }
